use atty::{self, Stream};

use crate::clap_app::CommandContext;
use clap::ArgMatches;

use bat::{config::Config, error::*, input::Input};

pub struct App {
    pub matches: ArgMatches<'static>,
    interactive_output: bool,
}

impl App {
    pub fn new() -> Result<Self> {
        #[cfg(windows)]
        let _ = ansi_term::enable_ansi_support();

        let interactive_output = atty::is(Stream::Stdout);

        Ok(App {
            matches: Self::matches(interactive_output)?,
            interactive_output,
        })
    }

    fn matches(interactive_output: bool) -> Result<ArgMatches<'static>> {
        let ctx = CommandContext::new(interactive_output);
        let args = if wild::args_os().nth(1) == Some("cache".into())
            || wild::args_os().any(|arg| arg == "--no-config")
        {
            // Skip the arguments in bats config file

            wild::args_os().collect::<Vec<_>>()
        } else {
            let mut cli_args = wild::args_os();

            // Read arguments from bats config file
            let mut args = ctx.args_from_env_or_config()?;

            // Put the zero-th CLI argument (program name) first
            args.insert(0, cli_args.next().unwrap());

            // .. and the rest at the end
            cli_args.for_each(|a| args.push(a));

            args
        };

        Ok(ctx.build_app().get_matches_from(args))
    }

    pub fn config(&self, inputs: &[Input]) -> Result<Config> {
        CommandContext::new(self.interactive_output).build_config(&self.matches, inputs)
    }

    pub fn inputs(&self) -> Result<Vec<Input>> {
        CommandContext::new(self.interactive_output).collect_inputs(&self.matches)
    }
}

